#include <stdio.h>

void show(int a[], int n)
{
    int i;
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
}

int main(void)
{
    int a[20], n, i, j, t, swapped;

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    for (i = 0; i < n - 1; i++) {
        swapped = 0;
        for (j = 0; j < n - 1 - i; j++) {
            if (a[j] > a[j + 1]) {
                t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
                swapped = 1;
            }
        }
        printf("Pass %d: ", i + 1);
        show(a, n);
        if (swapped == 0)
            /* already sorted */
            break;
    }
    printf("Sorted: ");
    show(a, n);
    return 0;
}

#include <stdio.h>

void bubble(int a[], int n)
{
    int i, j, t, comp = 0, swp = 0, flag;
    for (i = 0; i < n - 1; i++) {
        flag = 0;
        for (j = 0; j < n - 1 - i; j++) {
            comp++;
            if (a[j] > a[j + 1]) {
                t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
                swp++;
                flag = 1;
            }
        }
        if (!flag) break;
    }
    printf("comp = %2d, swaps = %2d\n",
           comp, swp);
}

