int a[8] = {25, 57, 48, 37,
             12, 92, 86, 33};
int n = 8;

void show(void)
{
    int i;
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
}

int partition(int lo, int hi)
{
    int p = a[lo], i = lo + 1, j = hi, t;
    while (1) {
        while (i <= hi && a[i] <= p)
            i++;
        while (a[j] > p)
            j--;
        if (i < j) {
            t = a[i];
            a[i] = a[j];
            a[j] = t;
        } else
            break;
    }
    /* pivot to place */
    a[lo] = a[j];
    a[j] = p;
    return j;
}

void quick(int lo, int hi)
{
    int k;
    if (lo < hi) {
        k = partition(lo, hi);
        printf("pivot %d -> [%d]: ",
               a[k], k);
        show();
        quick(lo, k - 1);
        quick(k + 1, hi);
    }
}

int main(void)
{
    printf("Input          : ");
    show();
    quick(0, n - 1);
    printf("Sorted         : ");
    show();
    return 0;
}

#include <stdio.h>

void merge(int a[], int l, int m, int r)
{
    int t[20], i = l, j = m + 1, k = 0;
    while (i <= m && j <= r) {
        if (a[i] <= a[j])
            t[k++] = a[i++];
        else
            t[k++] = a[j++];
    }
    while (i <= m) t[k++] = a[i++];
    while (j <= r) t[k++] = a[j++];
    for (i = l, k = 0; i <= r; i++, k++)
        a[i] = t[k];
}

void msort(int a[], int l, int r)
{
    int m, i;
    if (l < r) {
        m = (l + r) / 2;
        msort(a, l, m);
        msort(a, m + 1, r);
        merge(a, l, m, r);
        printf("merged [%d..%d]: ", l, r);
        for (i = l; i <= r; i++)
            printf("%d ", a[i]);
        printf("\n");
    }
}

int main(void)
{
    int a[7] = {38, 27, 43, 3, 9, 82, 10};
    int i;
    msort(a, 0, 6);
    printf("Sorted: ");
    for (i = 0; i < 7; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[8] = {170, 45, 75, 90,
                802, 24, 2, 66};
    int n = 8, b[10][8], cnt[10];
    int i, j, k, d, max = a[0];
    int exp = 1, pass = 0;

    for (i = 1; i < n; i++)
        if (a[i] > max) max = a[i];

    while (max / exp > 0) {
        for (d = 0; d < 10; d++)
            cnt[d] = 0;
        for (i = 0; i < n; i++) {
            d = (a[i] / exp) % 10;
            b[d][cnt[d]++] = a[i];
        }
        k = 0;
        for (d = 0; d < 10; d++)
            for (j = 0; j < cnt[d]; j++)
                a[k++] = b[d][j];
        printf("Pass %d: ", ++pass);
        for (i = 0; i < n; i++)
            printf("%d ", a[i]);
        printf("\n");
        exp *= 10;
    }
    return 0;
}

