#include <stdio.h>

int bsearch_r(int a[], int low, int high,
              int key)
{
    int mid;
    if (low > high)
        /* base case */
        return -1;
    mid = (low + high) / 2;
    if (a[mid] == key)
        return mid;
    if (key < a[mid])
        return bsearch_r(a, low, mid - 1,
                         key);
    return bsearch_r(a, mid + 1, high,
                     key);
}

