#include <stdio.h>
#define M 10

int table[M];

void insert(int key)
{
    int h = key % M, i = h;
    while (table[i] != -1)
        i = (i + 1) % M;   /* next slot */
    table[i] = key;
    printf("%d: h=%d slot=%d", key, h, i);
    if (i != h)
        printf(" (collision)");
    printf("\n");
}

int search(int key)
{
    int i = key % M, c = 0;
    while (table[i] != -1 && c < M) {
        if (table[i] == key) return i;
        i = (i + 1) % M;
        c++;
    }
    return -1;
}

int main(void)
{
    int k[6] = {1234, 5678, 4321, 9087,
                2466, 3456};
    int i;
    for (i = 0; i < M; i++) table[i] = -1;
    for (i = 0; i < 6; i++) insert(k[i]);
    for (i = 0; i < M; i++)
        printf("[%d] %d\n", i, table[i]);
    printf("search 3456 -> slot %d\n",
           search(3456));
    printf("search 1111 -> slot %d\n",
           search(1111));
    return 0;
}

#include <stdio.h>
