int digits(long x)
{
    int d = 0;
    do { d++; x /= 10; } while (x > 0);
    return d;
}

int midsquare(long k)       /* 2 digits */
{
    long sq = k * k, p = 1;
    int n = digits(sq), drop, i;
    drop = n - (n - 2) / 2 - 2;
    for (i = 0; i < drop; i++)
        p *= 10;
    printf("k=%ld k^2=%ld ", k, sq);
    return (int)((sq / p) % 100);
}

int folding(long k)    /* parts of 2 */
{
    char s[20];
    int i, sum = 0, n;
    sprintf(s, "%ld", k);
    n = strlen(s);
    for (i = 0; i < n; i += 2) {
        int part = s[i] - '0';
        if (i + 1 < n)
            part = part * 10
                   + s[i + 1] - '0';
        sum += part;
    }
    printf("k=%ld sum=%d ", k, sum);
    return sum % 100;
}

int main(void)
{
    printf("-> %d\n", midsquare(3205));
    printf("-> %d\n", midsquare(4567));
    printf("-> %d\n", folding(12345678));
    printf("-> %d\n", folding(9876543));
    return 0;
}

#include <stdio.h>

int bubble(int a[], int n)
{
    int i, j, t, c = 0, f;
    for (i = 0; i < n - 1; i++) {
        f = 0;
        for (j = 0; j < n - 1 - i; j++) {
            c++;
            if (a[j] > a[j + 1]) {
                t = a[j]; a[j] = a[j + 1];
                a[j + 1] = t; f = 1;
            }
        }
        if (!f) break;
    }
    return c;
}

int selection(int a[], int n)
{
    int i, j, m, t, c = 0;
    for (i = 0; i < n - 1; i++) {
        m = i;
        for (j = i + 1; j < n; j++) {
            c++;
            if (a[j] < a[m]) m = j;
        }
        t = a[i]; a[i] = a[m]; a[m] = t;
    }
    return c;
}

int insertion(int a[], int n)
{
    int i, j, k, c = 0;
    for (i = 1; i < n; i++) {
        k = a[i];
        for (j = i - 1; j >= 0; j--) {
            c++;
            if (a[j] <= k) break;
            a[j + 1] = a[j];
        }
        a[j + 1] = k;
    }
    return c;
}

